   return typeof nit === "string" && /^\d{5,12}$/.test(nit);
 }

+// RF-004: descuento opcional en porcentaje (0 a 100, hasta 2 decimales), redondeado al centavo por línea.
+// Se pasa a centésimas de punto para redondear con aritmética entera (ADR-001).
+function totalLineaCentavos({ cantidad, precioUnitarioCentavos, descuentoPorcentaje = 0 }) {
+  if (typeof descuentoPorcentaje !== "number" || !(descuentoPorcentaje >= 0 && descuentoPorcentaje <= 100))
+    throw new RangeError("Descuento inválido: debe ser un porcentaje de 0 a 100");
+  const descuentoCentesimas = Math.round(descuentoPorcentaje * 100);
+  if (Math.abs(descuentoPorcentaje * 100 - descuentoCentesimas) > 1e-6)
+    throw new RangeError("Descuento inválido: admite hasta 2 decimales");
+  return Math.round((cantidad * precioUnitarioCentavos * (10000 - descuentoCentesimas)) / 10000);
+}
